quantized_levels = {0→0.5, 1→5.333, 2→10.167, 3→15.0}

// 正常值0.5→0 (精确=0.5)，1.2→0 (恢复=0.5, error=-0.7)，0.8→0 (恢复=0.5, error=-0.3)
